import { buildPlaybackPanel } from './solution';
import type { Track } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

function throwsTypeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error: unknown) {
    if (error instanceof TypeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: did not throw`);
}

const first: Track = { id: 'song-1', title: 'First' };
const second: Track = { id: 'song-2', title: 'Second' };
const tracks = [first, second];
const sources = { 'song-1': '/audio/one.mp3', 'song-2': '/audio/two.mp3' };
const panel = buildPlaybackPanel('song-2', tracks, sources);
equal(panel, {
  track: { id: 'song-2', title: 'Second' },
  source: '/audio/two.mp3',
  placement: 'bottom',
  height: 80,
  theme: 'dark',
}, 'normal panel');
assert(panel !== null && panel.track !== second, 'track is copied');
second.title = 'Changed';
assert(panel !== null && panel.track.title === 'Second', 'panel is stable after input track mutation');
equal(tracks.map((track) => track.id), ['song-1', 'song-2'], 'track array is not mutated');

equal(buildPlaybackPanel(null, [], {}), null, 'null active ID');
equal(buildPlaybackPanel('missing', tracks, sources), null, 'missing track');
equal(buildPlaybackPanel('song-1', tracks, {}), null, 'missing source');
equal(buildPlaybackPanel('song-1', tracks, { 'song-1': '' }), null, 'empty source');

const duplicates: Track[] = [
  { id: 'dup', title: 'First match' },
  { id: 'dup', title: 'Second match' },
];
const duplicatePanel = buildPlaybackPanel('dup', duplicates, { dup: 'stream' });
assert(duplicatePanel !== null && duplicatePanel.track.title === 'First match', 'first duplicate track is selected');

throwsTypeError(() => buildPlaybackPanel('', [], {}), 'empty active ID');
throwsTypeError(
  () => buildPlaybackPanel('valid', [{ id: 'valid', title: 'Valid' }, { id: '', title: 'Malformed' }], { valid: 'stream' }),
  'inactive malformed track ID',
);

